"""Medium-size random jobs with duplicate, tautological and impossible predicates."""
import random

NUMERIC = ('time', 'size', 'count')


def make_job(rng, index):
    nfields = rng.randint(1, 3)
    fields = []
    for i in range(nfields):
        kind = rng.choice(['time', 'size', 'count', 'id', 'flag'])
        size = rng.choice([1, 2, 3])
        domain = sorted(rng.sample(range(0, 50), size))
        fields.append({'name': f'g{i}', 'type': kind, 'domain': domain})
    slots = rng.randint(1, 2)
    width = rng.randint(1, 4)
    names = [f['name'] for f in fields]
    types = {f['name']: f['type'] for f in fields}
    numeric = [n for n in names if types[n] in NUMERIC]

    def make_cmp():
        field = rng.choice(names)
        ftype = types[field]
        op = rng.choice(['eq', 'ne'] if ftype in ('id', 'flag') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge'])
        shape = rng.choice(['ref', 'const', 'sum', 'scale', 'const'])
        if shape == 'ref' or not numeric:
            left = {'ref': [rng.randrange(slots), field]}
        elif shape == 'const':
            left = {'const': rng.randint(0, 40), 'type': ftype}
        elif shape == 'sum':
            pool = [n for n in names if types[n] == ftype] if ftype in NUMERIC else numeric
            if not pool:
                left = {'ref': [rng.randrange(slots), field]}
            else:
                refs = [[rng.randrange(slots), rng.choice(pool)] for _ in range(rng.randint(1, slots))]
                refs = list({tuple(r): r for r in refs}.values())
                left = {'sum': refs} if refs else {'ref': [rng.randrange(slots), field]}
        else:
            pool = numeric
            if not pool:
                left = {'ref': [rng.randrange(slots), field]}
            else:
                left = {'scale': rng.randint(0, 9), 'ref': [rng.randrange(slots), rng.choice(pool)]}
        # right side with the same type
        if types.get('x') is None:
            pass
        if ftype in ('id', 'flag'):
            right = {'const': rng.randint(0, 40), 'type': ftype}
        else:
            right = {'const': rng.randint(0, 40), 'type': ftype}
        return {'kind': 'cmp', 'left': left, 'op': op, 'right': right}

    def make_any_all():
        field = rng.choice(names)
        ftype = types[field]
        op = rng.choice(['eq', 'ne'] if ftype in ('id', 'flag') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge'])
        return {'kind': rng.choice(['any', 'all']), 'field': field, 'op': op, 'value': rng.randint(0, 30)}

    pool_of_predicates = [make_cmp, make_any_all]
    base = [rng.choice(pool_of_predicates)() for _ in range(rng.randint(1, 6))]
    predicates = []
    for pred in base:
        predicates.append(pred)
        if rng.random() < 0.35:
            predicates.append(json_copy(pred))       # duplicate semantics, distinct id
        if rng.random() < 0.15:
            predicates.append(tautology(rng, fields, slots))
    npred = len(predicates)

    def random_window():
        return [[rng.choice(f['domain']) for f in fields] for _ in range(slots)]

    train = [random_window() for _ in range(rng.randint(1, 8))]
    approved = []
    for _ in range(rng.randint(0, 4)):
        size = rng.randint(1, min(width, npred))
        clause = sorted(rng.sample(range(npred), size))
        if clause not in approved:
            approved.append(clause)
    queries = []
    for _ in range(rng.randint(0, 4)):
        field = rng.choice(names)
        target = [rng.randrange(slots), field]
        fixed = []
        used = {tuple(target)}
        for _ in range(rng.randint(0, 2)):
            f = rng.choice(names)
            ref = [rng.randrange(slots), f]
            if tuple(ref) in used:
                continue
            used.add(tuple(ref))
            fixed.append({'ref': ref, 'value': rng.choice([f['domain'] for f in fields if f['name'] == f][0])})
        prefix = rng.choice(['', '0', '1', '10', '01', '2', '3', '4', '5'])
        queries.append({'target': target, 'prefix': prefix, 'fixed': fixed})
    return {'fields': fields, 'slots': slots, 'predicates': predicates, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}


def json_copy(value):
    import copy
    return copy.deepcopy(value)


def tautology(rng, fields, slots):
    field = rng.choice(fields)
    ftype = field['type']
    if ftype in ('id', 'flag'):
        value = field['domain'][0]
        return {'kind': 'cmp', 'left': {'ref': [0, field['name']]}, 'op': 'eq',
                'right': {'const': value, 'type': ftype}}
    value = max(field['domain'])
    return {'kind': 'cmp', 'left': {'const': value, 'type': ftype}, 'op': 'le',
            'right': {'const': value, 'type': ftype}}
